#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint   FrameCount;
    float  amount;        // px scale
    float  center_x;      // 0..1
    float  center_y;      // 0..1
    float  radial_k;      // radial distortion coeff
    float  tangential_k;  // tangential distortion coeff
};

struct VSIn { float4 pos [[attribute(0)]]; float2 uv [[attribute(1)]]; };
struct VSOut { float4 pos [[position]]; float2 uv; };

vertex VSOut main0(VSIn in [[stage_in]], constant Uniforms &u [[buffer(0)]]) {
    VSOut o; o.pos = u.MVP * in.pos; o.uv = in.uv; return o;
}

static inline float2 distort(float2 uv, float2 c, float radial_k, float tang_k){
    float2 p = uv - c;
    float r2 = dot(p,p);
    float2 radial = p * (1.0 + radial_k * r2);
    float2 tang = float2(
        2.0 * p.x * p.y,
        r2 + 2.0 * p.y * p.y
    ) * tang_k;
    return c + radial + tang;
}

fragment float4 fragment_main(
    VSOut in [[stage_in]],
    texture2d<float> src [[texture(0)]],
    constant Uniforms &u [[buffer(0)]]
){
    constexpr sampler smp(mag_filter::linear, min_filter::linear, address::clamp_to_edge);

    float2 uv = in.uv;
    float2 center = float2(u.center_x, u.center_y);

    // Scale amount in pixels to UV
    float2 px = 1.0 / u.OutputSize.xy;
    float amt = u.amount;

    // Distort each channel slightly differently for CA
    float2 uvR = distort(uv + amt*px, center, u.radial_k*1.10, u.tangential_k*1.10);
    float2 uvG = distort(uv,          center, u.radial_k*0.90, u.tangential_k*0.90);
    float2 uvB = distort(uv - amt*px, center, u.radial_k*1.00, u.tangential_k*1.00);

    float r = src.sample(smp, uvR).r;
    float g = src.sample(smp, uvG).g;
    float b = src.sample(smp, uvB).b;

    float3 col = float3(r,g,b);
    return float4(saturate(col), 1.0);
}

